<?php
require_once __DIR__ . '/_auth.php';
require_once dirname(__DIR__) . '/lib/property-store.php';
$owner=owner_require_login();
$rows=[];
foreach (li_all_properties() as $r) {
  if (($r['status'] ?? '') === 'OWNER_DELETED') continue;
  $ownerId=$r['owner']['account_id'] ?? null;
  $ownerMobile=$r['owner']['mobile'] ?? null;
  if (($ownerId && $ownerId === ($owner['id']??'')) || (!$ownerId && normalize_mobile((string)$ownerMobile) === normalize_mobile((string)($owner['mobile']??'')))) $rows[]=$r;
}
?>
