ded-lg hover:bg-white/10" href="/owner/edit-property.php?reference_id=<?=rawurlencode($ref)?>">✏️ Edit Property</a><button type="button" class="w-full text-left px-3 py-2 rounded-lg hover:bg-white/10" onclick="document.getElementById('detail-<?=htmlspecialchars($ref)?>').showModal()">👁 View Details</button><?php if($isLive): ?><a class="block px-3 py-2 rounded-lg hover:bg-white/10 text-emerald-300" target="_blank" href="<?=htmlspecialchars($liveUrl)?>">↗ Open Live Page</a><?php endif; ?><a class="block px-3 py-2 rounded-lg hover:bg-red-500/10 text-red-300" href="/owner/delete-property.php?reference_id=<?=rawurlencode($ref)?>">🗑 Delete Property</a></div></details></div></div><?php if(!empty($r['verification']['notes'])): ?><div class="mt-3 p-3 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-200 text-sm">Team note: <?=htmlspecialchars((string)$r['verification']['notes'])?></div><?php endif; ?><dialog id="detail-<?=htmlspecialchars($ref)?>" class="backdrop:bg-black/70 rounded-2xl bg-slate-900 text-white p-0 w-[92%] max-w-lg"><div class="p-5"><div class="flex justify-between"><h3 class="font-black text-lg">Property Details</h3><button onclick="this.closest('dialog').close()" class="text-slate-400 text-xl">×</button></div><div class="mt-4 grid gap-2 text-sm"><div><b>Purpose:</b> <?=htmlspecialchars($p['purpose']??'')?></div><div><b>Type:</b> <?=htmlspecialchars($p['type']??'')?></div><div><b>Configuration:</b> <?=htmlspecialchars($p['configuration']??'')?></div><div><b>Area:</b> <?=htmlspecialchars($p['area']??'')?></div><div><b>Price:</b> ₹<?=htmlspecialchars($p['price']??'')?></div><div><b>Project:</b> <?=htmlspecialchars($p['project_name']??'')?></div><div><b>Location:</b> <?=htmlspecialchars(($p['locality']??'').', '.($p['city']??''))?></div><div><b>Description:</b> <?=nl2br(htmlspecialchars($p['description']??''))?></div></div><button onclick="this.closest('dialog').close()" class="mt-5 w-full py-2 rounded-xl bg-white/10">Close</button></div></dialog></div><?php endforeach; endif; ?></div></main><script>async function shareProperty(path){const url=new URL(path,location.origin).href;try{if(navigator.share){await navigator.share({title:'My Leads India Property',url});}else{await navigator.clipboard.writeText(url);alert('Property link copied');}}catch(e){}}</script></body></html>